import React, { useState, useEffect } from "react";
import { FaPlus, FaEdit, FaTrash, FaEye, FaEyeSlash } from "react-icons/fa";
import { bannerAPI } from "../../utils/api";
import BannerForm from "./BannerForm";
import "./AdminComponents.css";

const BannerManagement = () => {
  const [banners, setBanners] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [editingBanner, setEditingBanner] = useState(null);
  const [error, setError] = useState("");

  useEffect(() => {
    fetchBanners();
  }, []);

  const fetchBanners = async () => {
    try {
      setLoading(true);
      const response = await bannerAPI.getAll();
      setBanners(response.data.data || []);
    } catch (error) {
      console.error("Error fetching banners:", error);
      setError("Failed to fetch banners");
    } finally {
      setLoading(false);
    }
  };

  const handleCreateBanner = () => {
    setEditingBanner(null);
    setShowForm(true);
  };

  const handleEditBanner = (banner) => {
    setEditingBanner(banner);
    setShowForm(true);
  };

  const handleDeleteBanner = async (bannerId) => {
    if (window.confirm("Are you sure you want to delete this banner?")) {
      try {
        await bannerAPI.delete(bannerId);
        await fetchBanners();
        setError("");
      } catch (error) {
        console.error("Error deleting banner:", error);
        setError("Failed to delete banner");
      }
    }
  };

  const handleToggleStatus = async (bannerId, currentStatus) => {
    try {
      await bannerAPI.update(bannerId, { isActive: !currentStatus });
      await fetchBanners();
      setError("");
    } catch (error) {
      console.error("Error updating banner status:", error);
      setError("Failed to update banner status");
    }
  };

  const handleFormSubmit = async (bannerData) => {
    try {
      if (editingBanner) {
        await bannerAPI.update(editingBanner._id, bannerData);
      } else {
        await bannerAPI.create(bannerData);
      }
      await fetchBanners();
      setShowForm(false);
      setEditingBanner(null);
      setError("");
    } catch (error) {
      console.error("Error saving banner:", error);
      setError("Error saving banner. Please try again.");
    }
  };

  const handleFormCancel = () => {
    setShowForm(false);
    setEditingBanner(null);
    setError("");
  };

  if (loading) {
    return (
      <div className="loading-container">
        <div className="loading-spinner">
          <div className="spinner"></div>
          <p>Loading banners...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="banner-management">
      <div className="section-header">
        <h2>Banner Management</h2>
        <button className="btn btn-primary" onClick={handleCreateBanner}>
          <FaPlus /> Add New Banner
        </button>
      </div>

      {error && <div className="error-message">{error}</div>}

      {showForm && (
        <BannerForm
          banner={editingBanner}
          onSubmit={handleFormSubmit}
          onCancel={handleFormCancel}
        />
      )}

      <div className="banners-grid">
        {banners.length === 0 ? (
          <div className="no-banners">
            <p>No banners found. Create your first banner to get started!</p>
          </div>
        ) : (
          banners.map((banner) => (
            <div key={banner._id} className="banner-card">
              <div className="banner-image">
                <img src={banner.image} alt={banner.title} />
                <div className="banner-overlay">
                  <button
                    className="btn btn-icon"
                    onClick={() => handleEditBanner(banner)}
                    title="Edit Banner"
                  >
                    <FaEdit />
                  </button>
                  <button
                    className="btn btn-icon btn-danger"
                    onClick={() => handleDeleteBanner(banner._id)}
                    title="Delete Banner"
                  >
                    <FaTrash />
                  </button>
                </div>
              </div>

              <div className="banner-info">
                <h3>{banner.title}</h3>
                <p>{banner.description}</p>
                <div className="banner-meta">
                  <span className={`status ${banner.isActive ? "active" : "inactive"}`}>
                    {banner.isActive ? "Active" : "Inactive"}
                  </span>
                  <span className="order">Order: {banner.order || 0}</span>
                </div>

                <div className="banner-actions">
                  <button
                    className={`btn btn-sm ${banner.isActive ? "btn-outline" : "btn-primary"}`}
                    onClick={() => handleToggleStatus(banner._id, banner.isActive)}
                  >
                    {banner.isActive ? <FaEyeSlash /> : <FaEye />}
                    {banner.isActive ? "Deactivate" : "Activate"}
                  </button>
                </div>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default BannerManagement;
